#include <stdio.h>
#include <string.h>

int main(void) {
    char watched[64];
    int n;
    if (scanf("watch %63s %d", watched, &n) != 2) {
        return 0;
    }
    long long current = 0;
    int stops = 0;
    for (int i = 0; i < n; i++) {
        int line;
        char name[64];
        long long value;
        if (scanf("%d %63s %lld", &line, name, &value) != 3) {
            break;
        }
        if (strcmp(name, watched) != 0 || value == current) {
            continue;
        }
        printf("строка %d: %lld -> %lld\n", line, current, value);
        current = value;
        stops++;
    }
    printf("остановок: %d\n", stops);
    return 0;
}

